import sys
from collections import deque

def main():
    x, y = map(int, sys.stdin.read().split())
    B = 2 * x + 30
    dist = [-1] * (B + 1)
    dist[x] = 0
    q = deque([x])
    while q:
        v = q.popleft()
        if v == y:
            break
        nxt = [v + 1, v - 1]
        if v % 11 == 0:
            nxt.append(v // 11)
        if v % 5 == 0:
            nxt.append(v // 5)
        for w in nxt:
            if 1 <= w <= B and dist[w] < 0:
                dist[w] = dist[v] + 1
                q.append(w)
    print(dist[y])

